def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.169.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.168.0"' not in init:
        sys.exit("ABORT: not at v3.168.0.")
    for k in ("monitoring_health", "advanced_sysadmin"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("SYS7", LESSONS_S7, QUESTIONS_S7, 9) + _validate("SYS8", LESSONS_S8, QUESTIONS_S8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("SYS 7", LESSONS_S7, QUESTIONS_S7, "monitoring_health",
         "Monitoring in ZhiftERP: the three reading rules (trend not point, exception not census, silence is a finding); the Error Log triage and its four patterns; the Scheduled Job Type/Log pulse check with the all-jobs-silent diagnosis; Background Jobs as the on-demand instrument with the three user-facing translations; the weekly people-read with its privacy posture; storage and reference-timing trends with evidenced escalation; the one-page health page and the three assembled cadences; and the incident log with its quarterly cause read."),
        ("SYS 8", LESSONS_S8, QUESTIONS_S8, "advanced_sysadmin",
         "Security and audit in ZhiftERP: the five layers and the honest threat picture; the completed password/session layer with the lost-device path; the two-factor rollout with method policy, written recovery procedure, and coverage read; the Version trail's three disciplines with track-changes confirmed on governed doctypes; the Deleted Document review and access-log reads; the security calendar and the six-section annual review; the six-step incident response with containment first; and the structural close — the handover and absence tests, and the track's eight laws."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.168.0"', '"3.169.0"'))
    print("  data: SYSADMIN 7 + 8 lessons + banks REPLACED (style v3) — Sysadmin track redo COMPLETE")
    print("wrote __version__ -> 3.169.0")


if __name__ == "__main__":
    main()
